"""Banner image for the VoiceMaster control panel (embedded so there is no extra file to upload)."""
import base64
import io

import discord

BANNER_NAME = "vm_banner.jpg"
BANNER_B64 = ""


def banner_file() -> discord.File:
    return discord.File(io.BytesIO(base64.b64decode(BANNER_B64)), filename=BANNER_NAME)
